parameters.jsCode:
const data = $input.item.json;
const children = data.children || [];

if (children.length === 0) {
  return [{ json: { parent_id: data.parent_id, parent_name: data.parent_name, summary: 'No children data available.', has_alerts: false } }];
}

const alerts = children.flatMap(child => {
  return (child.recent_scores || []).filter(s => s.score < 50).map(s => ({
    student: child.student_name,
    topic: s.topic,
    score: s.score,
    date: s.date,
  }));
});

const weakTopicLines = children.flatMap(child =>
  (child.weak_topics || []).map(t => `• ${child.student_name}: ${t.topic || t}`)
);

const summaryLines = [
  `Weekly Report for ${data.parent_name}`,
  '',
  'Children: ' + children.map(c => c.student_name).join(', '),
  '',
  weakTopicLines.length > 0 ? 'Topics needing attention:\n' + weakTopicLines.join('\n') : 'All topics are on track this week!',
  '',
  alerts.length > 0 ? `Low scores this week: ${alerts.length} alert(s) — please review with your children.` : 'No low scores this week.',
];

return [{
  json: {
    parent_id: data.parent_id,
    parent_name: data.parent_name,
    tenant_code: data.tenant_code,
    summary: summaryLines.join('\n'),
    has_alerts: alerts.length > 0,
    alert_count: alerts.length,
    children_count: children.length,
  }
}];

